-- Manual addition (not generated by `prisma migrate diff`): make AuditLog
-- append only for every role, including the table owner. See spec 0002, AC-14.
--
-- 0001 only REVOKEs UPDATE/DELETE from a role named hearme_app, which does
-- nothing when that role is missing or when the app connects as the owner
-- (Neon's default). A trigger fires for every role, so it holds either way.

CREATE FUNCTION "audit_log_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- The one allowed change: the AdminUser foreign key's ON DELETE SET NULL
  -- clearing actorAdminUserId when that admin is removed. Nothing else on
  -- the row may differ.
  IF TG_OP = 'UPDATE'
     AND OLD."actorAdminUserId" IS NOT NULL
     AND NEW."actorAdminUserId" IS NULL
     AND (to_jsonb(NEW) - 'actorAdminUserId') = (to_jsonb(OLD) - 'actorAdminUserId')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'AuditLog is append only (% blocked)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER "AuditLog_append_only_rows"
  BEFORE UPDATE OR DELETE ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION "audit_log_append_only"();

CREATE TRIGGER "AuditLog_append_only_truncate"
  BEFORE TRUNCATE ON "AuditLog"
  FOR EACH STATEMENT EXECUTE FUNCTION "audit_log_append_only"();

REVOKE UPDATE, DELETE, TRUNCATE ON "AuditLog" FROM PUBLIC;
